// Product MCP server tests: initialize, tools/list, each tool (happy + bad input),
// server card shape, and write-method rejection.

import { describe, expect, it, vi } from "vitest";

const reportServerEvent = vi.fn();
vi.mock("@/lib/analytics-server", () => ({
	reportServerEvent: (...args: unknown[]) => reportServerEvent(...args),
	reportServerEvents: vi.fn(),
}));

// Helper to create a JSON-RPC request
function rpcRequest(method: string, params?: Record<string, unknown>, id = 1) {
	return {
		jsonrpc: "2.0" as const,
		id,
		method,
		params,
	};
}

describe("Product MCP Actions Server", () => {
	describe("initialize", () => {
		it("returns server info and capabilities on initialize", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(rpcRequest("initialize")),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			expect(body.jsonrpc).toBe("2.0");
			expect(body.result.serverInfo.name).toContain("Actions MCP");
			expect(body.result.capabilities.tools).toBeDefined();
		});
	});

	describe("tools/list", () => {
		it("returns all three action tools with correct annotations", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(rpcRequest("tools/list")),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			const tools = body.result.tools;
			expect(tools.length).toBe(3);
			const names = tools.map((t: { name: string }) => t.name);
			expect(names).toContain("orchestkit_list_skills");
			expect(names).toContain("orchestkit_install_plan");
			expect(names).toContain("orchestkit_doctor_check");
			// All tools must be read-only
			for (const t of tools) {
				expect(t.annotations.readOnlyHint).toBe(true);
				expect(t.annotations.destructiveHint).toBe(false);
			}
		});
	});

	describe("orchestkit_list_skills", () => {
		it("returns user-invocable skills with docs URLs", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", { name: "orchestkit_list_skills" }),
					),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			const text = body.result.content[0].text;
			expect(text).toContain("OrchestKit Skills");
			expect(text).toContain("https://orchestkit.yonyon.ai/docs/reference/skills");
		});
	});

	describe("orchestkit_install_plan", () => {
		it("returns install plan with install command", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", { name: "orchestkit_install_plan" }),
					),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			const text = body.result.content[0].text;
			expect(text).toContain("Installation");
			expect(text).toContain("claude plugin");
		});

		it("returns error for invalid skill names", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_install_plan",
							arguments: { skills: ["nonexistent-skill"] },
						}),
					),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			expect(body.result.isError).toBe(true);
			expect(body.result.content[0].text).toContain("Invalid skill names");
		});

		it("refuses a known skill that is not user-invocable", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_install_plan",
							arguments: { skills: ["accessibility"] },
						}),
					),
				}),
			);
			const body = await res.json();
			expect(body.result.isError).toBe(true);
			expect(body.result.content[0].text).toContain(
				"Skills not available for direct invocation: accessibility",
			);
		});

		it("returns matching, documented suggestions for a goal", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_install_plan",
							arguments: { goal: "Debug a failing CI run" },
						}),
					),
				}),
			);
			const body = await res.json();
			const text = body.result.content[0].text;
			expect(text).toContain("## Suggested Skills");
			expect(text).toContain("**ci-debug**");
			expect(text).toContain("/docs/reference/skills/ci-debug");
		});
	});

	describe("orchestkit_doctor_check", () => {
		it("validates a hooks config fragment", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_doctor_check",
							arguments: {
								config: JSON.stringify({
									hooks: {
										PreToolUse: [
											{
												matcher: "Edit",
												hooks: [{ type: "command", command: "my-hook.sh" }],
											},
										],
									},
								}),
								type: "hooks",
							},
						}),
					),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			const text = body.result.content[0].text;
			expect(text).toContain("Status: PASS");
			expect(text).toContain("supported basic JSON-object checks");
		});

		it("does not report PASS for non-JSON configuration", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_doctor_check",
							arguments: {
								config: [
									"---",
									"name: example",
									"description: YAML frontmatter",
									"---",
								].join("\n"),
								type: "skill",
							},
						}),
					),
				}),
			);
			const body = await res.json();
			const text = body.result.content[0].text;
			expect(body.result.isError).toBe(true);
			expect(text).toContain("Status: NOT VALIDATED");
			expect(text).not.toContain("Status: PASS");
		});

		it("reports malformed entries in event-keyed hooks objects", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_doctor_check",
							arguments: {
								config: JSON.stringify({
									hooks: { PreToolUse: { matcher: "Edit", hooks: [] } },
								}),
								type: "hooks",
							},
						}),
					),
				}),
			);
			const body = await res.json();
			const text = body.result.content[0].text;
			expect(text).toContain("Status: ISSUES FOUND");
			expect(text).toContain("Hook event 'PreToolUse' must contain an array");
			expect(text).not.toContain("Status: PASS");
		});

		it("does not report PASS for JSON values that are not objects", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			for (const config of ["null", "[]", "true", "\"skill\""]) {
				const res = await POST(
					new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
						method: "POST",
						headers: { "content-type": "application/json" },
						body: JSON.stringify(
							rpcRequest("tools/call", {
								name: "orchestkit_doctor_check",
								arguments: { config, type: "skill" },
							}),
						),
					}),
				);
				const body = await res.json();
				const text = body.result.content[0].text;
				expect(body.result.isError).toBe(true);
				expect(text).toContain("Status: NOT VALIDATED");
				expect(text).not.toContain("Status: PASS");
			}
		});

		it("returns error for missing config", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(
						rpcRequest("tools/call", {
							name: "orchestkit_doctor_check",
							arguments: { type: "hooks" },
						}),
					),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			expect(body.result.isError).toBe(true);
		});
	});

	describe("write method rejection", () => {
		it("rejects resources/write as read-only server", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(rpcRequest("resources/write")),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			expect(body.error).toBeDefined();
			expect(body.error.message).toContain("read-only");
		});

		it("rejects prompts/write as read-only server", async () => {
			const { POST } = await import("@/app/api/mcp/actions/route");
			const res = await POST(
				new Request("https://orchestkit.yonyon.ai/api/mcp/actions", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify(rpcRequest("prompts/write")),
				}),
			);
			expect(res.status).toBe(200);
			const body = await res.json();
			expect(body.error).toBeDefined();
			expect(body.error.message).toContain("read-only");
		});
	});
});

